JSON.stringify((()=>{const b=(e)=>{const r=e.getBoundingClientRect();return{l:r.left,t:r.top,r:r.right,b:r.bottom,cx:(r.left+r.right)/2,cy:(r.top+r.bottom)/2};};
const dist=(a,c)=>{const dx=Math.max(0,c.l-a.r,a.l-c.r),dy=Math.max(0,c.t-a.b,a.t-c.b);return Math.hypot(dx,dy);};
const all=[...document.querySelectorAll("header.chrome a, header.chrome summary, header.chrome button, header.chrome p.also")].filter((e)=>e.offsetParent!==null);
const m=(e)=>{const p=b(e);const o=all.filter((x)=>x!==e&&!x.contains(e)&&!e.contains(x));return{edge:Math.round(Math.min(...o.map((x)=>dist(p,b(x))))*10)/10,centre:Math.round(Math.min(...o.map((x)=>{const q=b(x);return Math.hypot(p.cx-q.cx,p.cy-q.cy);}))*10)/10,h:Math.round(p.b-p.t)};};
const atl=document.querySelector("summary.atelier-press"),learn=document.querySelector(".learn1155");const c=document.querySelector(".corner.tr").getBoundingClientRect();
return{atelier:m(atl),learn:m(learn),toCorner:Math.round(c.left-b(learn).r),sameRow:!(c.bottom<=b(learn).t||b(learn).b<=c.top)};})())

